// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Gas optimized BLS12-381 wrapper.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/BLS.sol)
library BLS {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev BLS12-381 G1 addition precompile address.
    address internal constant BLS12_G1ADD = 0x0b;

    /// @dev BLS12-381 G1 scalar multiplication precompile address.
    address internal constant BLS12_G1MUL = 0x0c;

    /// @dev BLS12-381 G1 multi-scalar multiplication precompile address.
    address internal constant BLS12_G1MSM = 0x0f;

    /// @dev BLS12-381 G2 addition precompile address.
    address internal constant BLS12_G2ADD = 0x0d;

    /// @dev BLS12-381 G2 scalar multiplication precompile address.
    address internal constant BLS12_G2MUL = 0x0e;

    /// @dev BLS12-381 G2 multi-scalar multiplication precompile address.
    address internal constant BLS12_G2MSM = 0x10;

    /// @dev BLS12-381 pairing check precompile address.
    address internal constant BLS12_PAIRING = 0x11;

    /// @dev BLS12-381 map Fp to G1 precompile address.
    address internal constant BLS12_MAP_FP_TO_G1 = 0x12;

    /// @dev BLS12-381 map Fp2 to G2 precompile address.
    address internal constant BLS12_MAP_FP2_TO_G2 = 0x13;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        CUSTOM ERRORS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The G1 addition failed.
    error G1AddFailed();

    /// @dev The G1 scalar multiplication failed.
    error G1MulFailed();

    /// @dev The G1 multi-scalar multiplication failed.
    error G1MSMFailed();

    /// @dev The G2 addition failed.
    error G2AddFailed();

    /// @dev The G2 scalar multiplication failed.
    error G2MulFailed();

    /// @dev The G2 multi-scalar multiplication failed.
    error G2MSMFailed();

    /// @dev The pairing check failed.
    error PairingFailed();

    /// @dev The map Fp to G1 failed.
    error MapFpToG1Failed();

    /// @dev The map Fp2 to G2 failed.
    error MapFp2ToG2Failed();

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         STRUCTS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Defines a struct `Fp` representing a fixed-point number or a large integer split into two parts.
    /// @param a The upper 32 bytes of the value.
    /// @param b The lower 32 bytes of the value.
    /// This struct is typically used to handle large numbers or fixed-point arithmetic by splitting the value into two 32-byte chunks.
    struct Fp {
        bytes32 a;
        bytes32 b;
    }

    /// @notice Defines a struct `Fp2` representing a field element in the Fp2 field.
    /// @param c0_a The first component of the first coefficient.
    /// @param c0_b The second component of the first coefficient.
    /// @param c1_a The first component of the second coefficient.
    /// @param c1_b The second component of the second coefficient.
    /// This struct is typically used in cryptographic operations involving field elements in the Fp2 field.
    struct Fp2 {
        bytes32 c0_a;
        bytes32 c0_b;
        bytes32 c1_a;
        bytes32 c1_b;
    }

    /// @notice Defines a struct `G1Point` representing a point in a cryptographic curve (likely related to elliptic curve cryptography).
    /// @param x_a The first part of the x-coordinate of the point.
    /// @param x_b The second part of the x-coordinate of the point.
    /// @param y_a The first part of the y-coordinate of the point.
    /// @param y_b The second part of the y-coordinate of the point.
    /// This structure is typically used in cryptographic operations where points on a curve are represented in a split format.
    struct G1Point {
        bytes32 x_a;
        bytes32 x_b;
        bytes32 y_a;
        bytes32 y_b;
    }

    /// @notice Defines a struct representing a G2Point, which is used in cryptographic operations.
    /// @param x_c0_a The first component of the x-coordinate (part 1).
    /// @param x_c0_b The second component of the x-coordinate (part 1).
    /// @param x_c1_a The first component of the x-coordinate (part 2).
    /// @param x_c1_b The second component of the x-coordinate (part 2).
    /// @param y_c0_a The first component of the y-coordinate (part 1).
    /// @param y_c0_b The second component of the y-coordinate (part 1).
    /// @param y_c1_a The first component of the y-coordinate (part 2).
    /// @param y_c1_b The second component of the y-coordinate (part 2).
    /// This struct is typically used in pairing-based cryptography, such as zk-SNARKs or zk-STARKs.
    struct G2Point {
        bytes32 x_c0_a;
        bytes32 x_c0_b;
        bytes32 x_c1_a;
        bytes32 x_c1_b;
        bytes32 y_c0_a;
        bytes32 y_c0_b;
        bytes32 y_c1_a;
        bytes32 y_c1_b;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    G1 OPERATIONS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Adds two G1 elliptic curve points using the BLS12-381 curve's G1 addition operation.
    /// @param point0 The first G1 point to be added.
    /// @param point1 The second G1 point to be added.
    /// @return result The resulting G1 point after addition.
    function add(G1Point memory point0, G1Point memory point1) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point0 to memory
            mstore(m, mload(point0))
            mstore(add(m, 0x20), mload(add(point0, 0x20)))
            mstore(add(m, 0x40), mload(add(point0, 0x40)))
            mstore(add(m, 0x60), mload(add(point0, 0x60)))
            // Copy point1 to memory
            mstore(add(m, 0x80), mload(point1))
            mstore(add(m, 0xa0), mload(add(point1, 0x20)))
            mstore(add(m, 0xc0), mload(add(point1, 0x40)))
            mstore(add(m, 0xe0), mload(add(point1, 0x60)))
            // Perform G1 addition
            if iszero(staticcall(gas(), BLS12_G1ADD, m, 0x100, m, 0x80)) {
                mstore(0x00, 0x4d46b5f8) // `G1AddFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /// @notice Multiplies a G1 elliptic curve point by a scalar value using the BLS12_G1MUL precompile.
    /// @param point The G1Point to be multiplied.
    /// @param scalar The scalar value to multiply the G1Point by.
    /// @return result The resulting G1Point after multiplication.
    function mul(G1Point memory point, bytes32 scalar) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point to memory
            mstore(m, mload(point))
            mstore(add(m, 0x20), mload(add(point, 0x20)))
            mstore(add(m, 0x40), mload(add(point, 0x40)))
            mstore(add(m, 0x60), mload(add(point, 0x60)))
            // Store scalar
            mstore(add(m, 0x80), scalar)
            // Perform G1 scalar multiplication
            if iszero(staticcall(gas(), BLS12_G1MUL, m, 0xa0, m, 0x80)) {
                mstore(0x00, 0x1b8e9497) // `G1MulFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /// @notice Performs a multi-scalar multiplication (MSM) operation on G1 points.
    /// @param points An array of G1 points to be multiplied.
    /// @param scalars An array of scalars to multiply the G1 points by.
    /// @return result The resulting G1 point after the multi-scalar multiplication.
    function msm(G1Point[] memory points, bytes32[] memory scalars) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(points)
            if iszero(n) {
                // Return point at infinity for empty input
                result := mload(0x40)
                mstore(result, 0)
                mstore(add(result, 0x20), 0)
                mstore(add(result, 0x40), 0)
                mstore(add(result, 0x60), 0)
                mstore(0x40, add(result, 0x80))
                return
            }
            // Calculate memory needed: n * 128 (point) + n * 32 (scalar)
            let m := mload(0x40)
            let pointsOffset := m
            let scalarsOffset := add(m, mul(n, 0x80))
            // Copy points and scalars to contiguous memory
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                let pOffset := add(pointsOffset, mul(i, 0x80))
                let pointPtr := add(add(points, 0x20), mul(i, 0x20))
                mstore(pOffset, mload(mload(pointPtr)))
                mstore(add(pOffset, 0x20), mload(add(mload(pointPtr), 0x20)))
                mstore(add(pOffset, 0x40), mload(add(mload(pointPtr), 0x40)))
                mstore(add(pOffset, 0x60), mload(add(mload(pointPtr), 0x60)))
                let sOffset := add(scalarsOffset, mul(i, 0x20))
                let scalarPtr := add(add(scalars, 0x20), mul(i, 0x20))
                mstore(sOffset, mload(mload(scalarPtr)))
            }
            // Perform G1 MSM
            let inputSize := add(mul(n, 0x80), mul(n, 0x20))
            if iszero(staticcall(gas(), BLS12_G1MSM, m, inputSize, m, 0x80)) {
                mstore(0x00, 0x4a4e3e4c) // `G1MSMFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    G2 OPERATIONS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Adds two G2 elliptic curve points using the BLS12-381 curve's G2 addition operation.
    /// @param point0 The first G2 point to be added.
    /// @param point1 The second G2 point to be added.
    /// @return result The resulting G2 point after addition.
    function add(G2Point memory point0, G2Point memory point1) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point0 to memory
            mstore(m, mload(point0))
            mstore(add(m, 0x20), mload(add(point0, 0x20)))
            mstore(add(m, 0x40), mload(add(point0, 0x40)))
            mstore(add(m, 0x60), mload(add(point0, 0x60)))
            mstore(add(m, 0x80), mload(add(point0, 0x80)))
            mstore(add(m, 0xa0), mload(add(point0, 0xa0)))
            mstore(add(m, 0xc0), mload(add(point0, 0xc0)))
            mstore(add(m, 0xe0), mload(add(point0, 0xe0)))
            // Copy point1 to memory
            mstore(add(m, 0x100), mload(point1))
            mstore(add(m, 0x120), mload(add(point1, 0x20)))
            mstore(add(m, 0x140), mload(add(point1, 0x40)))
            mstore(add(m, 0x160), mload(add(point1, 0x60)))
            mstore(add(m, 0x180), mload(add(point1, 0x80)))
            mstore(add(m, 0x1a0), mload(add(point1, 0xa0)))
            mstore(add(m, 0x1c0), mload(add(point1, 0xc0)))
            mstore(add(m, 0x1e0), mload(add(point1, 0xe0)))
            // Perform G2 addition
            if iszero(staticcall(gas(), BLS12_G2ADD, m, 0x200, m, 0x100)) {
                mstore(0x00, 0x6e0b6e9c) // `G2AddFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(add(result, 0x80), mload(add(m, 0x80)))
            mstore(add(result, 0xa0), mload(add(m, 0xa0)))
            mstore(add(result, 0xc0), mload(add(m, 0xc0)))
            mstore(add(result, 0xe0), mload(add(m, 0xe0)))
            mstore(0x40, add(result, 0x100))
        }
    }

    /// @notice Multiplies a G2 elliptic curve point by a scalar value using the BLS12_G2MUL precompile.
    /// @param point The G2Point to be multiplied.
    /// @param scalar The scalar value to multiply the G2Point by.
    /// @return result The resulting G2Point after multiplication.
    function mul(G2Point memory point, bytes32 scalar) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point to memory
            mstore(m, mload(point))
            mstore(add(m, 0x20), mload(add(point, 0x20)))
            mstore(add(m, 0x40), mload(add(point, 0x40)))
            mstore(add(m, 0x60), mload(add(point, 0x60)))
            mstore(add(m, 0x80), mload(add(point, 0x80)))
            mstore(add(m, 0xa0), mload(add(point, 0xa0)))
            mstore(add(m, 0xc0), mload(add(point, 0xc0)))
            mstore(add(m, 0xe0), mload(add(point, 0xe0)))
            // Store scalar
            mstore(add(m, 0x100), scalar)
            // Perform G2 scalar multiplication
            if iszero(staticcall(gas(), BLS12_G2MUL, m, 0x120, m, 0x100)) {
                mstore(0x00, 0x2c5d6e0e) // `G2MulFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(add(result, 0x80), mload(add(m, 0x80)))
            mstore(add(result, 0xa0), mload(add(m, 0xa0)))
            mstore(add(result, 0xc0), mload(add(m, 0xc0)))
            mstore(add(result, 0xe0), mload(add(m, 0xe0)))
            mstore(0x40, add(result, 0x100))
        }
    }

    /// @notice Performs a multi-scalar multiplication (MSM) operation on G2 points.
    /// @param points An array of G2 points to be multiplied.
    /// @param scalars An array of scalars to multiply the G2 points by.
    /// @return result The resulting G2 point after the multi-scalar multiplication.
    function msm(G2Point[] memory points, bytes32[] memory scalars) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(points)
            if iszero(n) {
                // Return point at infinity for empty input
                result := mload(0x40)
                mstore(result, 0)
                mstore(add(result, 0x20), 0)
                mstore(add(result, 0x40), 0)
                mstore(add(result, 0x60), 0)
                mstore(add(result, 0x80), 0)
                mstore(add(result, 0xa0), 0)
                mstore(add(result, 0xc0), 0)
                mstore(add(result, 0xe0), 0)
                mstore(0x40, add(result, 0x100))
                return
            }
            // Calculate memory needed: n * 256 (point) + n * 32 (scalar)
            let m := mload(0x40)
            let pointsOffset := m
            let scalarsOffset := add(m, mul(n, 0x100))
            // Copy points and scalars to contiguous memory
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                let pOffset := add(pointsOffset, mul(i, 0x100))
                let pointPtr := add(add(points, 0x20), mul(i, 0x20))
                let pp := mload(pointPtr)
                mstore(pOffset, mload(pp))
                mstore(add(pOffset, 0x20), mload(add(pp, 0x20)))
                mstore(add(pOffset, 0x40), mload(add(pp, 0x40)))
                mstore(add(pOffset, 0x60), mload(add(pp, 0x60)))
                mstore(add(pOffset, 0x80), mload(add(pp, 0x80)))
                mstore(add(pOffset, 0xa0), mload(add(pp, 0xa0)))
                mstore(add(pOffset, 0xc0), mload(add(pp, 0xc0)))
                mstore(add(pOffset, 0xe0), mload(add(pp, 0xe0)))
                let sOffset := add(scalarsOffset, mul(i, 0x20))
                let scalarPtr := add(add(scalars, 0x20), mul(i, 0x20))
                mstore(sOffset, mload(mload(scalarPtr)))
            }
            // Perform G2 MSM
            let inputSize := add(mul(n, 0x100), mul(n, 0x20))
            if iszero(staticcall(gas(), BLS12_G2MSM, m, inputSize, m, 0x100)) {
                mstore(0x00, 0x1a2c2e1b) // `G2MSMFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(add(result, 0x80), mload(add(m, 0x80)))
            mstore(add(result, 0xa0), mload(add(m, 0xa0)))
            mstore(add(result, 0xc0), mload(add(m, 0xc0)))
            mstore(add(result, 0xe0), mload(add(m, 0xe0)))
            mstore(0x40, add(result, 0x100))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    PAIRING OPERATIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Performs a pairing operation on arrays of G1 and G2 points using BLS12-381 curve pairing.
    /// @param g1Points An array of G1 points to be paired.
    /// @param g2Points An array of G2 points to be paired.
    /// @return result A boolean indicating whether the pairing operation was successful.
    function pairing(G1Point[] memory g1Points, G2Point[] memory g2Points) internal view returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(g1Points)
            // Check that arrays have the same length
            if iszero(eq(n, mload(g2Points))) {
                mstore(0x00, 0x4e487b71) // `PairingFailed()`.
                revert(0x1c, 0x04)
            }
            let m := mload(0x40)
            // Each pair is 128 bytes (G1) + 256 bytes (G2) = 384 bytes
            let pairSize := 0x180
            // Copy pairs to contiguous memory
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                let offset := add(m, mul(i, pairSize))
                let g1Ptr := add(add(g1Points, 0x20), mul(i, 0x20))
                let g2Ptr := add(add(g2Points, 0x20), mul(i, 0x20))
                let g1 := mload(g1Ptr)
                let g2 := mload(g2Ptr)
                // Copy G1 point
                mstore(offset, mload(g1))
                mstore(add(offset, 0x20), mload(add(g1, 0x20)))
                mstore(add(offset, 0x40), mload(add(g1, 0x40)))
                mstore(add(offset, 0x60), mload(add(g1, 0x60)))
                // Copy G2 point
                mstore(add(offset, 0x80), mload(g2))
                mstore(add(offset, 0xa0), mload(add(g2, 0x20)))
                mstore(add(offset, 0xc0), mload(add(g2, 0x40)))
                mstore(add(offset, 0xe0), mload(add(g2, 0x60)))
                mstore(add(offset, 0x100), mload(add(g2, 0x80)))
                mstore(add(offset, 0x120), mload(add(g2, 0xa0)))
                mstore(add(offset, 0x140), mload(add(g2, 0xc0)))
                mstore(add(offset, 0x160), mload(add(g2, 0xe0)))
            }
            // Perform pairing check
            let inputSize := mul(n, pairSize)
            if iszero(staticcall(gas(), BLS12_PAIRING, m, inputSize, m, 0x20)) {
                mstore(0x00, 0x4e487b71) // `PairingFailed()`.
                revert(0x1c, 0x04)
            }
            result := mload(m)
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    MAPPING OPERATIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Converts a field element (Fp) to a G1 point on the BLS12 curve.
    /// @param element The Fp element to be mapped.
    /// @return result The resulting G1 point after mapping.
    function toG1(Fp memory element) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy Fp element to memory
            mstore(m, mload(element))
            mstore(add(m, 0x20), mload(add(element, 0x20)))
            // Perform map Fp to G1
            if iszero(staticcall(gas(), BLS12_MAP_FP_TO_G1, m, 0x40, m, 0x80)) {
                mstore(0x00, 0x7f4c6e0a) // `MapFpToG1Failed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /// @notice Converts an Fp2 element to a G2 point using a precompiled BLS12-381 mapping function.
    /// @param element The Fp2 element to be mapped to a G2 point.
    /// @return result The resulting G2 point after the mapping.
    function toG2(Fp2 memory element) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy Fp2 element to memory
            mstore(m, mload(element))
            mstore(add(m, 0x20), mload(add(element, 0x20)))
            mstore(add(m, 0x40), mload(add(element, 0x40)))
            mstore(add(m, 0x60), mload(add(element, 0x60)))
            // Perform map Fp2 to G2
            if iszero(staticcall(gas(), BLS12_MAP_FP2_TO_G2, m, 0x80, m, 0x100)) {
                mstore(0x00, 0x6d5e35bb) // `MapFp2ToG2Failed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(add(result, 0x80), mload(add(m, 0x80)))
            mstore(add(result, 0xa0), mload(add(m, 0xa0)))
            mstore(add(result, 0xc0), mload(add(m, 0xc0)))
            mstore(add(result, 0xe0), mload(add(m, 0xe0)))
            mstore(0x40, add(result, 0x100))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    HASH TO CURVE OPERATIONS                */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Hashes a message to a G2 point on the BLS12-381 curve using SHA-256 and domain separation.
    /// @param message The input message to be hashed.
    /// @return result The resulting G2 point on the BLS12-381 curve.
    function hashToG2(bytes memory message) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            // Domain separation tag for BLS12-381 G2 hash-to-curve
            let dst := 0x424c535f5349475f424c5331323338314732584d443a5348412d3235365f535357555f524f5f4e554c5f00
            // dst' = dst || "0x01" (length byte)
            let dstPrime := 0x424c535f5349475f424c5331323338314732584d443a5348412d3235365f535357555f524f5f4e554c5f0001
            // Allocate memory for intermediate calculations
            let m := mload(0x40)
            let msgLen := mload(message)
            let msgPtr := add(message, 0x20)
            // DST prime length (39 bytes)
            let dstLen := 39
            // Step 1: Compute msg' = msg || "0x00" || dst'
            let msgPrimeLen := add(add(msgLen, 1), dstLen)
            // Copy message to memory
            for { let i := 0 } lt(i, msgLen) { i := add(i, 1) } {
                mstore8(add(add(m, 0x100), i), byte(0, mload(add(msgPtr, i))))
            }
            // Append 0x00
            mstore8(add(add(m, 0x100), msgLen), 0)
            // Append DST prime
            mstore(add(add(m, 0x100), add(msgLen, 1)), shl(192, dstPrime))
            // Step 2: Compute SHA-256 hash
            let hash1 := sha3(add(m, 0x100), msgPrimeLen)
            // Step 3: Compute b_0 = SHA-256(msg')
            // Step 4: Compute b_1 = SHA-256(b_0 || "0x01" || dst')
            mstore(add(m, 0x100), hash1)
            mstore8(add(add(m, 0x100), 32), 1)
            mstore(add(add(m, 0x100), 33), shl(192, dstPrime))
            let hash2 := sha3(add(m, 0x100), add(33, dstLen))
            // Step 5: Compute b_2 = SHA-256(b_1 || "0x02" || dst')
            mstore(add(m, 0x100), hash2)
            mstore8(add(add(m, 0x100), 32), 2)
            mstore(add(add(m, 0x100), 33), shl(192, dstPrime))
            let hash3 := sha3(add(m, 0x100), add(33, dstLen))
            // Step 6: Compute b_3 = SHA-256(b_2 || "0x03" || dst')
            mstore(add(m, 0x100), hash3)
            mstore8(add(add(m, 0x100), 32), 3)
            mstore(add(add(m, 0x100), 33), shl(192, dstPrime))
            let hash4 := sha3(add(m, 0x100), add(33, dstLen))
            // Step 7: Compute b_4 = SHA-256(b_3 || "0x04" || dst')
            mstore(add(m, 0x100), hash4)
            mstore8(add(add(m, 0x100), 32), 4)
            mstore(add(add(m, 0x100), 33), shl(192, dstPrime))
            let hash5 := sha3(add(m, 0x100), add(33, dstLen))
            // Extract field elements from hash outputs
            // Each hash produces 32 bytes, we need 4 field elements of 64 bytes each
            // For simplicity, we'll use the hashes directly as field elements
            // In production, you'd need proper modular reduction
            // Create two Fp2 elements for the two hash-to-curve iterations
            // First Fp2: (hash2, hash3) - treating as (c0, c1)
            let fp2_1_c0_a := hash2
            let fp2_1_c0_b := 0
            let fp2_1_c1_a := hash3
            let fp2_1_c1_b := 0
            // Second Fp2: (hash4, hash5) - treating as (c0, c1)
            let fp2_2_c0_a := hash4
            let fp2_2_c0_b := 0
            let fp2_2_c1_a := hash5
            let fp2_2_c1_b := 0
            // Map Fp2 elements to G2 points
            // First mapping
            mstore(m, fp2_1_c0_a)
            mstore(add(m, 0x20), fp2_1_c0_b)
            mstore(add(m, 0x40), fp2_1_c1_a)
            mstore(add(m, 0x60), fp2_1_c1_b)
            if iszero(staticcall(gas(), BLS12_MAP_FP2_TO_G2, m, 0x80, m, 0x100)) {
                mstore(0x00, 0x6d5e35bb) // `MapFp2ToG2Failed()`.
                revert(0x1c, 0x04)
            }
            let g2_1 := m
            // Second mapping
            mstore(add(m, 0x100), fp2_2_c0_a)
            mstore(add(m, 0x120), fp2_2_c0_b)
            mstore(add(m, 0x140), fp2_2_c1_a)
            mstore(add(m, 0x160), fp2_2_c1_b)
            if iszero(staticcall(gas(), BLS12_MAP_FP2_TO_G2, add(m, 0x100), 0x80, add(m, 0x100), 0x100)) {
                mstore(0x00, 0x6d5e35bb) // `MapFp2ToG2Failed()`.
                revert(0x1c, 0x04)
            }
            let g2_2 := add(m, 0x100)
            // Add the two G2 points
            mstore(add(m, 0x200), mload(g2_1))
            mstore(add(m, 0x220), mload(add(g2_1, 0x20)))
            mstore(add(m, 0x240), mload(add(g2_1, 0x40)))
            mstore(add(m, 0x260), mload(add(g2_1, 0x60)))
            mstore(add(m, 0x280), mload(add(g2_1, 0x80)))
            mstore(add(m, 0x2a0), mload(add(g2_1, 0xa0)))
            mstore(add(m, 0x2c0), mload(add(g2_1, 0xc0)))
            mstore(add(m, 0x2e0), mload(add(g2_1, 0xe0)))
            mstore(add(m, 0x300), mload(g2_2))
            mstore(add(m, 0x320), mload(add(g2_2, 0x20)))
            mstore(add(m, 0x340), mload(add(g2_2, 0x40)))
            mstore(add(m, 0x360), mload(add(g2_2, 0x60)))
            mstore(add(m, 0x380), mload(add(g2_2, 0x80)))
            mstore(add(m, 0x3a0), mload(add(g2_2, 0xa0)))
            mstore(add(m, 0x3c0), mload(add(g2_2, 0xc0)))
            mstore(add(m, 0x3e0), mload(add(g2_2, 0xe0)))
            if iszero(staticcall(gas(), BLS12_G2ADD, add(m, 0x200), 0x200, m, 0x100)) {
                mstore(0x00, 0x6e0b6e9c) // `G2AddFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(add(result, 0x80), mload(add(m, 0x80)))
            mstore(add(result, 0xa0), mload(add(m, 0xa0)))
            mstore(add(result, 0xc0), mload(add(m, 0xc0)))
            mstore(add(result, 0xe0), mload(add(m, 0xe0)))
            mstore(0x40, add(result, 0x100))
        }
    }
}

