// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Gas optimized BLS12-381 wrapper.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/BLS.sol)
library BLS {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev BLS12-381 G1 addition precompile address.
    address internal constant BLS12_G1ADD = 0x0b;

    /// @dev BLS12-381 G1 scalar multiplication precompile address.
    address internal constant BLS12_G1MUL = 0x0c;

    /// @dev BLS12-381 G1 multi-scalar multiplication precompile address.
    address internal constant BLS12_G1MSM = 0x0f;

    /// @dev BLS12-381 G2 addition precompile address.
    address internal constant BLS12_G2ADD = 0x0d;

    /// @dev BLS12-381 G2 scalar multiplication precompile address.
    address internal constant BLS12_G2MUL = 0x0e;

    /// @dev BLS12-381 G2 multi-scalar multiplication precompile address.
    address internal constant BLS12_G2MSM = 0x10;

    /// @dev BLS12-381 pairing check precompile address.
    address internal constant BLS12_PAIRING = 0x11;

    /// @dev BLS12-381 map Fp to G1 precompile address.
    address internal constant BLS12_MAP_FP_TO_G1 = 0x12;

    /// @dev BLS12-381 map Fp2 to G2 precompile address.
    address internal constant BLS12_MAP_FP2_TO_G2 = 0x13;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        CUSTOM ERRORS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The G1 addition failed.
    error G1AddFailed();

    /// @dev The G1 scalar multiplication failed.
    error G1MulFailed();

    /// @dev The G1 multi-scalar multiplication failed.
    error G1MSMFailed();

    /// @dev The G2 addition failed.
    error G2AddFailed();

    /// @dev The G2 scalar multiplication failed.
    error G2MulFailed();

    /// @dev The G2 multi-scalar multiplication failed.
    error G2MSMFailed();

    /// @dev The pairing check failed.
    error PairingFailed();

    /// @dev The map Fp to G1 failed.
    error MapFpToG1Failed();

    /// @dev The map Fp2 to G2 failed.
    error MapFp2ToG2Failed();

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         STRUCTS                            */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Defines a struct `Fp` representing a fixed-point number or a large integer split into two parts.
    /// @param a The upper 32 bytes of the value.
    /// @param b The lower 32 bytes of the value.
    /// This struct is typically used to handle large numbers or fixed-point arithmetic by splitting the value into two 32-byte chunks.
    struct Fp {
        bytes32 a;
        bytes32 b;
    }

    /// @notice Defines a struct `Fp2` representing a field element in the Fp2 field.
    /// @param c0_a The first component of the first coefficient.
    /// @param c0_b The second component of the first coefficient.
    /// @param c1_a The first component of the second coefficient.
    /// @param c1_b The second component of the second coefficient.
    /// This struct is typically used in cryptographic operations involving field elements in the Fp2 field.
    struct Fp2 {
        bytes32 c0_a;
        bytes32 c0_b;
        bytes32 c1_a;
        bytes32 c1_b;
    }

    /// @notice Defines a struct `G1Point` representing a point in a cryptographic curve (likely related to elliptic curve cryptography).
    /// @param x_a The first part of the x-coordinate of the point.
    /// @param x_b The second part of the x-coordinate of the point.
    /// @param y_a The first part of the y-coordinate of the point.
    /// @param y_b The second part of the y-coordinate of the point.
    /// This structure is typically used in cryptographic operations where points on a curve are represented in a split format.
    struct G1Point {
        bytes32 x_a;
        bytes32 x_b;
        bytes32 y_a;
        bytes32 y_b;
    }

    /// @notice Defines a struct representing a G2Point, which is used in cryptographic operations.
    /// @param x_c0_a The first component of the x-coordinate (part 1).
    /// @param x_c0_b The second component of the x-coordinate (part 1).
    /// @param x_c1_a The first component of the x-coordinate (part 2).
    /// @param x_c1_b The second component of the x-coordinate (part 2).
    /// @param y_c0_a The first component of the y-coordinate (part 1).
    /// @param y_c0_b The second component of the y-coordinate (part 1).
    /// @param y_c1_a The first component of the y-coordinate (part 2).
    /// @param y_c1_b The second component of the y-coordinate (part 2).
    /// This struct is typically used in pairing-based cryptography, such as zk-SNARKs or zk-STARKs.
    struct G2Point {
        bytes32 x_c0_a;
        bytes32 x_c0_b;
        bytes32 x_c1_a;
        bytes32 x_c1_b;
        bytes32 y_c0_a;
        bytes32 y_c0_b;
        bytes32 y_c1_a;
        bytes32 y_c1_b;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    G1 OPERATIONS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Adds two G1 elliptic curve points using the BLS12-381 curve's G1 addition operation.
    /// @param point0 The first G1 point to be added.
    /// @param point1 The second G1 point to be added.
    /// @return result The resulting G1 point after addition.
    function add(G1Point memory point0, G1Point memory point1) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point0 to memory
            mstore(m, mload(point0))
            mstore(add(m, 0x20), mload(add(point0, 0x20)))
            mstore(add(m, 0x40), mload(add(point0, 0x40)))
            mstore(add(m, 0x60), mload(add(point0, 0x60)))
            // Copy point1 to memory
            mstore(add(m, 0x80), mload(point1))
            mstore(add(m, 0xa0), mload(add(point1, 0x20)))
            mstore(add(m, 0xc0), mload(add(point1, 0x40)))
            mstore(add(m, 0xe0), mload(add(point1, 0x60)))
            // Perform G1 addition
            if iszero(staticcall(gas(), BLS12_G1ADD, m, 0x100, m, 0x80)) {
                mstore(0x00, 0x4d46b5f8) // `G1AddFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /// @notice Multiplies a G1 elliptic curve point by a scalar value using the BLS12_G1MUL precompile.
    /// @param point The G1Point to be multiplied.
    /// @param scalar The scalar value to multiply the G1Point by.
    /// @return result The resulting G1Point after multiplication.
    function mul(G1Point memory point, bytes32 scalar) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            // Copy point to memory
            mstore(m, mload(point))
            mstore(add(m, 0x20), mload(add(point, 0x20)))
            mstore(add(m, 0x40), mload(add(point, 0x40)))
            mstore(add(m, 0x60), mload(add(point, 0x60)))
            // Store scalar
            mstore(add(m, 0x80), scalar)
            // Perform G1 scalar multiplication
            if iszero(staticcall(gas(), BLS12_G1MUL, m, 0xa0, m, 0x80)) {
                mstore(0x00, 0x1b8e9497) // `G1MulFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

    /// @notice Performs a multi-scalar multiplication (MSM) operation on G1 points.
    /// @param points An array of G1 points to be multiplied.
    /// @param scalars An array of scalars to multiply the G1 points by.
    /// @return result The resulting G1 point after the multi-scalar multiplication.
    function msm(G1Point[] memory points, bytes32[] memory scalars) internal view returns (G1Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(points)
            if iszero(n) {
                // Return point at infinity for empty input
                result := mload(0x40)
                mstore(result, 0)
                mstore(add(result, 0x20), 0)
                mstore(add(result, 0x40), 0)
                mstore(add(result, 0x60), 0)
                mstore(0x40, add(result, 0x80))
                return
            }
            // Calculate memory needed: n * 128 (point) + n * 32 (scalar)
            let m := mload(0x40)
            let pointsOffset := m
            let scalarsOffset := add(m, mul(n, 0x80))
            // Copy points and scalars to contiguous memory
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                let pOffset := add(pointsOffset, mul(i, 0x80))
                let pointPtr := add(add(points, 0x20), mul(i, 0x20))
                mstore(pOffset, mload(mload(pointPtr)))
                mstore(add(pOffset, 0x20), mload(add(mload(pointPtr), 0x20)))
                mstore(add(pOffset, 0x40), mload(add(mload(pointPtr), 0x40)))
                mstore(add(pOffset, 0x60), mload(add(mload(pointPtr), 0x60)))
                let sOffset := add(scalarsOffset, mul(i, 0x20))
                let scalarPtr := add(add(scalars, 0x20), mul(i, 0x20))
                mstore(sOffset, mload(mload(scalarPtr)))
            }
            // Perform G1 MSM
            let inputSize := add(mul(n, 0x80), mul(n, 0x20))
            if iszero(staticcall(gas(), BLS12_G1MSM, m, inputSize, m, 0x80)) {
                mstore(0x00, 0x4a4e3e4c) // `G1MSMFailed()`.
                revert(0x1c, 0x04)
            }
            // Store result
            result := mload(0x40)
            mstore(result, mload(m))
            mstore(add(result, 0x20), mload(add(m, 0x20)))
            mstore(add(result, 0x40), mload(add(m, 0x40)))
            mstore(add(result, 0x60), mload(add(m, 0x60)))
            mstore(0x40, add(result, 0x80))
        }
    }

