    /*                    HASH TO CURVE OPERATIONS                */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Hashes a message to a G2 point on the BLS12-381 curve using SHA-256 and domain separation.
    /// @param message The input message to be hashed.
    /// @return result The resulting G2 point on the BLS12-381 curve.
    function hashToG2(bytes memory message) internal view returns (G2Point memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            // Domain separation tag for BLS12-381 G2 hash-to-curve
            let dst := 0x424c535f5349475f424c5331323338314732584d443a5348412d3235365f535357555f524f5f4e554c5f00
            // dst' = dst || "0x01" (length byte)
            let dstPrime := 0x424c535f5349475f424c5331323338314732584d443a5348412d3235365f535357555f524f5f4e554c5f0001
            // Allocate memory for intermediate calculations
            let m := mload(0x40)
            let msgLen := mload(message)
            let msgPtr := add(message, 0x20)
            // DST prime length (39 bytes)
            let dstLen := 39
            // Step 1: Compute msg' = msg || "0x00" || dst'
            let msgPrimeLen := add(add(msgLen, 1), dstLen)
            // Copy message to memory
            for { let i := 0 } lt(i, msgLen) { i := add(i, 1) } {
                mstore8(add(add(m, 0x100), i), byte(0, mload(add(msgPtr, i))))
